export * as Suggestions from './suggestions.tsx';
export type {
  ItemProps as SuggestionsItemProps,
  RootOwnProps as SuggestionsRootOwnProps,
  RootProps as SuggestionsRootProps,
} from './suggestions.tsx';

@layer hj.components {
  /* Customise: --hj-suggestions-height (chip height, default 36px) */
  .hj-suggestions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .hj-suggestions-item {
    --_i: 10;
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    max-width: 100%;
    height: var(--hj-suggestions-height, 36px);
    padding: 0 14px;
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg-dim);
    font: 500 13.5px / 1 var(--hj-font-sans);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
    /* One clock: 24 ms a chip, counting stops at ten. */
    animation: hj-suggestions-rise var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle) both;
    animation-delay: calc(var(--_i) * var(--hj-stagger));
  }
  .hj-suggestions-item:nth-child(1) {
    --_i: 0;
  }
  .hj-suggestions-item:nth-child(2) {
    --_i: 1;
  }
  .hj-suggestions-item:nth-child(3) {
    --_i: 2;
  }
  .hj-suggestions-item:nth-child(4) {
    --_i: 3;
  }
  .hj-suggestions-item:nth-child(5) {
    --_i: 4;
  }
  .hj-suggestions-item:nth-child(6) {
    --_i: 5;
  }
  .hj-suggestions-item:nth-child(7) {
    --_i: 6;
  }
  .hj-suggestions-item:nth-child(8) {
    --_i: 7;
  }
  .hj-suggestions-item:nth-child(9) {
    --_i: 8;
  }
  .hj-suggestions-item:nth-child(10) {
    --_i: 9;
  }
  @keyframes hj-suggestions-rise {
    from {
      opacity: 0;
      transform: translateY(calc(var(--hj-rise) * var(--hj-travel)));
    }
  }
  .hj-suggestions-item:hover:not([data-disabled]) {
    background: var(--hj-accent-soft);
    box-shadow: inset 0 0 0 1px transparent;
    color: var(--hj-accent);
  }
  .hj-suggestions-item:active:not([data-disabled]) {
    transform: scale(var(--hj-press));
    transition-duration: 70ms;
  }
  .hj-suggestions-item[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
  .hj-suggestions-icon {
    display: inline-flex;
    flex: none;
    font-size: 15px;
    line-height: 0;
    color: var(--hj-fg-mute);
  }
  .hj-suggestions-item:hover .hj-suggestions-icon {
    color: inherit;
  }
  .hj-suggestions-icon svg {
    width: 1em;
    height: 1em;
  }
}

'use client';
import { Button as BaseButton } from '@base-ui/react/button';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

const SelectContext = React.createContext<((prompt: string) => void) | undefined>(undefined);

/** Props hanji adds to the row. */
export interface RootOwnProps {
  /** Called with the chosen suggestion's prompt. */
  onSelect?: (prompt: string) => void;
  /** Accessible name for the group. @default 'Suggestions' */
  label?: string;
}
export interface RootProps
  extends RootOwnProps, Omit<React.ComponentProps<'div'>, 'className' | 'onSelect'> {
  className?: string;
  render?: useRender.RenderProp;
}

/**
 * A row of prompts the person can send with one tap. Chips cascade in on mount — 24 ms apart,
 * counting stops at ten.
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    onSelect,
    label = 'Suggestions',
    className,
    render,
    children,
    ...rest
  } = withDefaults(config, 'Suggestions.Root', props);
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      role: 'group',
      'aria-label': label,
      ...rest,
      className: cls(config, 'Suggestions.Root', 'hj-suggestions', className) as string | undefined,
      children: <SelectContext.Provider value={onSelect}>{children}</SelectContext.Provider>,
    },
  });
}

export interface ItemOwnProps {
  /** What gets sent. Defaults to the chip's text when children is a string. */
  prompt?: string;
  /** A leading glyph. */
  icon?: React.ReactNode;
}
export interface ItemProps extends ItemOwnProps, BaseButton.Props {}

/** One suggestion chip. */
export function Item(props: ItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const onSelect = React.useContext(SelectContext);
  const { prompt, icon, className, children, onClick, ...rest } = withDefaults(
    config,
    'Suggestions.Item',
    props,
  );
  return (
    <BaseButton
      type="button"
      {...rest}
      className={cls(config, 'Suggestions.Item', 'hj-suggestions-item', className)}
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        const value = prompt ?? (typeof children === 'string' ? children : '');
        if (value) onSelect?.(value);
      }}
    >
      {icon ? (
        <span className={config.unstyled ? undefined : 'hj-suggestions-icon'} aria-hidden="true">
          {icon}
        </span>
      ) : null}
      {children}
    </BaseButton>
  );
}
